      "jd": "薪资：6000‑7000 元 / 月\n上班时间：8：00-12：00    13：30-18：00\n要求：男女不限，大专及以上学历，至少 1 年采购助理 / 供应链相关工作经验。\n\n岗位职责：\n1. 协助采购开展供应商对接、询价、比价、核价工作，整理供应商资料档案；\n2. 根据生产排产计划跟进物料需求，协助下达采购订单，跟进物料交期，及时反馈物料到货异常；\n3. 负责采购单据、合同、对账单据整理、登记、归档，做好台账记录；\n4. 对接仓库，核对来料信息，协助处理来料核对、对账等工作；\n5. 跟踪物料库存情况，配合做好物料库存统计，协助处理物料异常、退换货事宜；\n6. 完成上级交办的其他采购相关辅助工作。\n\n任职要求：\n1. 大专及以上学历，男女不限，具备 1 年及以上采购助理、供应链、物料跟单相关工作经验；\n2. 熟练使用 Office 办公软件，会做数据台账，具备基础单据、报表整理能力；\n3. 工作细心严谨，沟通协调能力好，有较强执行力与责任心；\n4. 了解制造业物料采购流程，有五金、金属材料、硬质合金行业经验优先；\n5. 服从工作安排，具备成本意识，能够跟进物料交期，及时反馈问题。\n\n\n员工福利：\n1. 薪酬结构：基本工资 + 岗位补贴 + 加班补贴，月薪 6‑7k；\n2. 食宿：公司包住 + 餐补，宿舍通风采光条件良好；\n3. 社保：全额缴纳五险一金，每年组织职业健康体检；\n4. 假期：国家法定节假日、年假，节日发放节日礼金；\n5. 培训发展：入职培训，内部学习提升机会；\n6. 员工活动：年会、生日会、团建、带薪旅游；\n7. 人文关怀：起居补贴、困难员工帮扶基金、亲人生病探望关怀。\n\n公司简介：\n深圳市三名佳智能有限公司专注硬质合金棒料精密焊接，主营钨钢棒料接长、钨钢‑高速钢 / 碳钢异种焊接，产品应用切削刀具、耐磨零件领域，服务 PCB、3C 电子、汽车、船舶精工等行业。公司业务订单稳定，秉持员工、客户、股东三方满意的企业宗旨，重视人才培养。\n\n＞ 欢迎有意向人员投递简历，一起深耕金属加工行业＜",
      "source": "实名企业直招",
