      "jd": "一、岗位职责\n\n（一）生产文职核心工作\n\n1. 负责车间生产工单录入、下发、跟进，收集整理车间生产原始记录，精准统计每日产量、原材料消耗、产品损耗，独立制作生产日报、周报、月报。\n\n2. 负责车间各类单据流转核对，包含领料单、退料单、成品入库单、报废单等，及时录入ERP系统，对接仓库、质检、采购部门，确保单据数据准确、账目清晰。\n\n3. 管理车间全套生产资料，归档工艺文件、生产配方、质检报告、SOP作业指导书、设备巡检记录等，配合工厂ZDHC、质量体系审核，保证资料完整可追溯。\n\n4. 负责车间员工考勤、加班、请假、调休数据统计汇总，建立专属台账，按时上报人事部门核对。\n\n5. 负责车间劳保用品、生产耗材、辅助物料的申购、登记、发放与库存台账管理，定期盘点，保障车间生产正常运转。\n\n6. 整理生产例会会议纪要、传达工厂生产通知，登记车间生产异常问题并及时上报跟进，完成上级安排的各类生产辅助工作。\n\n（二）日常行政内勤工作\n\n1. 负责工厂日常行政事务，包含来访客户、面试人员接待，厂区卫生、办公环境日常巡检与统筹协调。\n\n2. 负责办公室办公用品、办公耗材的盘点、申购、发放及台账管理，管控行政物资成本。\n\n3. 负责工厂各类文件、通知、公告的编辑、排版、下发与存档，整理公司行政档案、资质文件、日常台账。\n\n4. 协助行政人事基础工作，包含员工入离职资料整理、考勤汇总、简单招聘信息发布、面试邀约登记。\n\n5. 负责工厂日常后勤对接，宿舍、水电、园区物业对接，节日福利、团建活动的辅助筹备工作。\n\n6. 协助整理工厂各类年审、报备、厂区日常资料，配合完成上级交办的其他行政临时工作。\n\n二、任职要求\n\n1. 中专及以上学历，20–38岁，熟练使用Word、Excel，精通VLOOKUP、数据透视表等基础办公函数，会操作ERP系统优先。\n\n2. 有化工、新材料、纺织助剂、工厂生产文员/行政内勤相关工作经验者优先，无经验踏实好学也可接纳。\n\n3. 做事细心严谨、责任心强、对数据敏感，具备良好的文档整理、资料归档能力，有保密意识。\n\n4. 沟通协调能力良好，服从工作安排，能适配工厂工作节奏，配合月底盘点、体系审核等阶段性忙碌工作。\n\n5. 了解基础工厂安全规范，品行端正、稳定稳定，无不良工作习惯。\n\n三、薪资福利\n\n1. 薪资稳定、按时发放，岗位轻松文职，无需一线生产操作、无体力劳作。\n\n2. 提供包吃包住，宿舍环境整洁，生活配套齐全。\n\n3. 入职购买五险\n5. 工厂订单稳定、氛围轻松，晋升渠道清晰，适合长期稳定发展。",
