      "jobKind": "2",
      "jd": "公司介绍：\n东亿洋山科技有限公司注册成立于2018年，注册资本5000万元，是一家专注于商用咖啡豆烘焙设备及全自动咖啡烘焙生产线研发、设计、生产与销售的工贸一体化企业。总部位于深圳市南山前海自贸区，并在深圳光明拥有一座4000平方米的独栋研发工厂记烘焙展厅。公司以“成为全球消费者最值得信赖的中国咖啡设备品牌”为愿景，致力于让YOSHAN成为国际知名的咖啡烘焙设备品牌。\n\n品牌成长与技术创新\n\n东亿洋山始终坚持自主研发与品牌建设，旗下 Yoshan 品牌涵盖了从小型精品咖啡烘焙机（每次烘焙500g，烘焙周期15分钟）到大型商用烘焙设备（1kg、2kg、12kg、30kg及300kg单次烘焙量）的全系列产品，是国内首区能够生产300kg超大型咖啡豆烘焙生产线的企业。\n\n        \n                  \n岗位职责：\n1、业务订单的维系以及跟进，协助业务跟进样机和大货生产进度及时汇报订单情况；\n\n2、负责与采购、工厂部门沟通，落实产品的基本信息；\n\n3、负责与货代方进行沟通，制作报关资料，追踪货物出货和核实货物运单；\n\n4、协助业务处理客户售后机退回给工厂分析&补货情况；\n\n5、准确制作生产过程中各类单据，保证单具的准确性；\n\n6、及时完成上级安排的工作和临时分配的任务。\n\n\n职位要求：\n1、本科及以上学历，商务英语、国际贸易等相关专业优先；\n2、英语四级级以上，听说读写流利，熟悉外贸报关资料（报关草单）；\n3、1年以上外贸跟单工作经验，熟悉外贸操作流程优先；\n4、熟悉office等办公软件，EXCEL熟练；\n5、具有优秀的沟通协调能力、表达能力及工作执行力、服从上级；\n6、一定要细心！细心！细心！\n\n任职条件：\n1、能够独立操作外贸跟单出货流程，跟进，反馈，订舱，出运等，解决各种相关异常；\n2、内外沟通协调能力佳；\n3、工作效率高，反馈速度及时。\n\n\n公司氛围：\n前海超A海景写字楼，舒适、整洁；\n和谐、积极、快乐的工作氛围，科学化、人本化的管理理念。\n\n晋升路径：\n外贸跟单——初级跟单——资深跟单——跟单组长——跟单主管",
