      "jd": "岗位职责\n\n1.对接各FAB厂，完成mask、wafer采购下单，结合销售订单及产销计划，监控物料匹配度，确保订单按时交付。\n\n2.跟踪mask、wafer在FAB厂的生产进度（流片、封装、测试），建立跟踪台账，及时处理并反馈生产异常。\n\n3.配合新品项目，对接研发及生产专员，监控新品物料采购、排产进度，保障新品项目按计划推进。\n\n4.统计mask、wafer采购、生产、交付数据，形成报表，推动工单及时关单，确保数据闭环。\n\n5.与FAB厂核对账单，排查差异，按公司流程申请付款并跟进进度。\n\n6.维护FAB厂对接关系，整理相关资料，辅助做好物料到货核对、库存异常反馈及文档归档工作。\n\n7.完成上级安排的其他工作。\n\n\n\n岗位要求\n\n1.学历专业：大专及以上，电子信息类、物流管理、统计学、供应链管理等相关专业优先；有FAB厂对接、芯片委外生产相关经验者加分。\n\n2.能力要求：具备订单转计划、物料需求分析能力，较强的跨部门（研发、销售、财务、FAB厂）协调沟通能力；对生产数据敏感，工作严谨，有问题排查及应急处理能力。\n\n3.技能要求：熟练使用Excel（数据统计、报表制作），熟悉ERP或生产管理系统；了解mask、wafer相关技术参数，能精准对接FAB厂沟通生产细节。\n\n4.职业素养：能承受工作紧迫感及赶货压力，责任心强、执行力强，原则性强，具备良好团队协作意识，对核心工作严格保密。\n\n5.其他：能适应偶尔紧急对接及少量加班，具备基础公文撰写能力，可清晰整理进度及异常报表。",
