      "jd": "岗位职责\n\n1. 根据排产计划在 ERP/MES 系统录入、下达生产工单，核对玻璃牌号、规格、批次、数量、客户信息，打印投料单、工序流转卡、批次标签，做好单据核对。\n2. 收集各工序报工数据，登记台账，统计产量、在制品、返工、报废、入库数据，每日更新。\n3. 编制生产日报、周报、月报，包含产量、良率、物料消耗、半成品库存等，按时提交给计划主管。\n4. 负责各类生产单据、流转记录、检验资料、订单文件、试产样品资料的整理、电子 + 纸质归档保管，方便批次追溯查阅。\n5. 核对原料、辅料领用、退料数据，配合半成品、成品盘点的数据登记工作。\n6. 样品单、试产工单信息登记、资料整理；完成主管安排的其他计划相关文职工作。\n\n 任职要求\n\n1. 大专及以上学历，有 PMC 文员、生产统计经验优先，光学玻璃、精密制造行业经验加分。\n2. 熟练使用 Office 办公软件，精通 Excel（数据透视表、VLOOKUP 等常用函数），会 ERP、MES 系统优先。\n3. 做事细心严谨，对数字敏感，重视批次、牌号管控，数据责任心强，不随意涂改单据。\n4. 沟通良好，能对接车间、质检、仓库收集数据；服从安排，稳定性强，适应工厂作息。\n5. 加分：了解光学玻璃基础生产流程，能看懂物料编码。",
