      "jd": "岗位职责\n1. 进出口报关单证处理：负责日常进口、出口货物报关资料的整理、核对与制作，包括发票、箱单、合同、报关单、备案资料等，确保单证信息准确、单单一致、单证一致，杜绝申报差错。\n2. 报关申报与跟进：协助报关员完成线上报关申报、审单、税费核对、放行跟进工作，及时跟踪货物通关状态。\n3. 台账与档案管理：建立进出口业务台账，精准记录报关日期、件号、品名、数量、报关单号、通关状态、税费信息等；负责报关资料、海关批复文件、原厂资料的分类归档、电子存档与纸质留存，保证资料完整可追溯。\n4.日常对接与沟通：对接货代、报关行、海关、仓库及公司业务部门，同步通关进度、反馈异常问题。\n5. 其他辅助工作：负责进出口税费统计、月度通关数据汇总、报表制作，完成上级交办的其他关务辅助工作。\n\n任职要求\n1. 学历专业：本科及以上学历，国际贸易、报关与国际货运、物流管理、商务英语等相关专业；\n2. 技能能力：熟悉进出口报关基本流程、海关申报规范，掌握单证制作、单据核对流程；熟练使用Office办公软件，能独立制作台账、报表；\n3. 经验要求：相关专业应届毕业生或有国际贸易、物流管理经验人员均可，有民用航空航材进出口报关经验者优先。\n4. 英语能力：英语4级，具备基础英文读写能力，可看懂原厂英文产品资料、报关英文单据。\n4. 核心素养：工作细致严谨、责任心强，对数字、产品参数敏感，具备极强的耐心和纠错能力；逻辑清晰，善于对接沟通，能高效处理通关异常问题。\n5. 职业素质：了解海关合规基本要求，原则性强，具备良好的职业操守，服从工作安排，学习能力强，能快速适配行业申报规则。",
