      "jd": "工作职责\n1. 生产保供调度：依据车间产能、物料消耗，制定日 / 周到货计划；监控厂区库存，预判缺料风险，动态调节到货节奏，保障生产线不停料、不爆仓。\n2. 三维库存管控：跟踪厂区、外仓、供应商三方库存，统计现货、在途、待发物料数据，做好外仓周转台账。\n3. 物料 & 车辆调度：对供应商发货、外仓收发转料、厂区收货、车间消耗数据核对匹配；结合天气、运力合理调派车辆，错峰进厂，跟进在途物料，及时处置运输异常。\n4. 台账报表输出：完成库存、到货、消耗、供应商供货等每日台账；输出周度供应链分析，做到账实相符，为各部门提供数据支持。\n5. 供应商协同管理：对接多家供应商，分配发货量，跟进供货履约情况，动态调整供货比例，保障原料供应稳定。\n6. 仓储跨部门协同：联动厂区及外仓仓库，统一作业标准，管控原料存储质量；配合制定月度、淡旺季原料备货保供计划。\n7. 异常处置：快速处理缺料、到货延误、数量差异、周转不畅等供应链各类问题，推动问题闭环。\n\n任职资格\n1. 供应链、物流、仓储、生产调度相关专业优先；有工厂原料调度、大宗散料供应链经验优先。\n2. 有生物质颗粒、煤炭、粮食、化肥、大宗散料工厂保供经验优先录用。\n3. 具备极强的数据统计、台账整理、数据分析能力，熟练使用 Excel 表格、数据透视、日报制作。\n4. 逻辑清晰、统筹能力强，能同时对接多供应商、多仓库、多车辆，抗压能力强。\n5. 执行力强、反应快，能适应生产连续性工作，可根据生产节奏应急调度。\n6. 沟通协调能力强，能高效对接供应商、仓库、车间、司机团队。\n\n岗位核心能力要求\n1. 会看产能、算消耗、控库存、排到货；\n2. 三维库存统筹：厂区 + 外仓 + 供应商库存全盘掌控；\n3. 每日数据闭环、问题闭环、风险预判闭环；\n4. 擅长车辆调度、错峰进厂、现场保供协调。",
      "source": "人力代招／猎头（主体待核）",
      "assessmentMethod": "2026-11-16保守规则复核＋重点样本人工复核，非HR资格确认",
