      "jd": "岗位职责：\n1、编制 FBA 采购计划，审核相关单据，通过 ERP 制定补货、发货计划；跟进仓库装箱、亚马逊货件创建，及时处理货件异常，做到日清闭环；\n2、结合库存及销量数据择优选择物流渠道，做好库存管控，防范断货、滞销、超储风险；\n3、每周更新补货规则，统计断货率、可售天数等库存指标，对接采购、仓库同步业务进展；\n4、负责报关标签维护、 填报等跨境合规相关工作；\n5、衔接运营、采购、物流各方，搭建产销协同机制，保障信息同步互通；\n6、参与 Prime Day、黑五网一等大促备货规划，测算备货数量并跟进落地执行；\n7、打通采购‑仓库‑亚马逊全链路，推进流程标准化，落实业务异常识别与预警；\n8、定期输出销售、库存分析报表，为管理层决策提供数据支撑。\n\n任职要求：\n1、全日制大专及以上学历，供应链管理、物流管理、电子商务等相关专业优先；\n2、1年以上需求计划、库存计划或供应链数据分析相关工作经验，有跨境电商行业经验者优先；\n3、数据分析能力强，熟练使用Excel(数据透视表、常用函数、图表制作)，会借助Al提升工作效率；\n4、熟悉库存管理基本逻辑(周转率、库龄、安全库存等)，对数据敏感，善于从数据中发现问题；\n5、具备优秀的跨部门协同能力，能主动拉通销售、采购、物流等多方资源，推动问题解决。\n6、抗压能力强，能适应跨境电商快节奏，逻辑清晰，有全局统筹意识，敢于直面冲突，推动落地。\n\n福利待遇：\n1、休假福利：周末双休，杜绝无效加班，依法享有各类法定假期；\n2、薪酬体系：底薪+绩效+年终奖，综合待遇优厚；\n3、团队活动：定期组织聚餐、旅游、下午茶，节日福利、团建活动不断；\n4、成长赋能：提供内、外训等多元化学习机会，助力员工能力持续提升；\n5、交通便利：距10号线《雅宝站》步行约300米，5分钟可达；\n6、周边配套：甲级写字楼，周边商业、餐饮配套完善，交通便利。\n\n上班时间：9:00-18:30 双休 \n工作地点：深圳龙岗区坂田街道星河WORLD生态大厦803",
