      "jd": "岗位职责：\n1.协助PMC和采购制定项目计划和时间表，监督项目进度，确保按时完成任务。\n2.协助采购跟进订单物料交期、核对账目，整理相关资料。\n3.协助采购进行供应商和合作伙伴管理，维护良好的合作关系。\n4.协助PMC处理一些日常工作。\n5.负责项目文档的撰写、整理和归档，确保项目文件的完整性和准确性。\n6.协助主管进行项目风险评估，提出应对措施，防范潜在风险。\n7.监督项目工作流程，并提出优化建议，不断改进工作效率和质量。\n8.能适应多岗位的调动协助。\n岗位要求：\n1.有工作经验优先，大专以上学历，电子专业。\n2.具有良好的沟通表达能力和团队协作精神。\n3.具有较强的抗压能力，能吃苦耐劳，有责任心，做事积极主动，踏实肯干，学习能力强，上进心强。\n4.具有较强的数据分析能力，逻辑思维能力，善于跨部门沟通。\n5.熟悉ERP系统，精通Excel常用公式。\n6.后期工作地点在东莞凤岗（十月份左右搬迁）",
