      "jd": "一.岗位职责：保障委外加工物料不断链、成品按时入库。\n1.跟原料采购：盯BOM物料 采购订单下达，追供应商到货时效。\n2.控库存配送：算外协厂日耗料需求，排物流 精准送料（JIT模式）。\n3.盯生产损耗：核车间 退补料数据，预警，超耗风险。\n4.保成品入库：追外协厂（日产出），对入库数（即时清点）。\n5.盘数据闭环：每日更新 物料在途/在制/成品库存；跑系统（自动报缺）（ERP/MES）\n\n二.任职资格：\n1.有过委外物控闭环管理相关经验至少一年以上；\n2.性格稳重踏实肯干，有良好的自驱力及主动性；\n3.沟通协调能力较好，大专以上学历，有过3C行业尤佳。",
