      "jd": "Major Accountabilities\n工作职责\n1. Order Entry & Master Data Management – Maintain customer and material master data, create technical inquiries and agreements, promptly enter sales orders, and coordinate cross-departmental approvals.\n2. Order Monitoring & Progress Reporting – Track order status and approval lead time, prepare analytical reports, and collaborate with finance and customer service to provide customers with updates on production, logistics, and invoicing progress.\n3. Collection & Payment Management – Assist in payment follow-up to encourage on-time payment, provide payment allocation recommendations, and track collections and customer feedback.\n4. Contract Change & Complaint Handling – Process contract change requests to ensure compliance, record and track technical, commercial, and logistics complaints, and urge timely resolution.\n5. Import Business Coordination – Maintain communication with overseas teams, track the entire import order process from entry to payment, and assist in achieving on-time delivery targets.\n1、订单录入与主数据管理：维护客户/物料主数据，创建技术询单及协议，及时录入销售订单并协调跨部门审批\n2、订单监控与进度反馈：跟踪订单状态及审批周期，编制分析报告，协同财务与客服向客户反馈生产、物流及开票进度\n3、回款与付款管理：协助催款推动按期付款，提供付款分配建议，跟踪回款及客户反馈\n4、合同变更与投诉处理：处理合同变更请求确保合规，记录并跟踪技术/商务/物流投诉，督促快速处置\n5、进口业务协调：与海外团队保持沟通，跟踪进口订单从录入至收款全过程，协助达成准时交付目标\n\nQualifications / Experience Required\n能力/经验要求\n1. Bachelor's degree or above.\n2. Full-process order management experience preferred.\n3. Familiar with SAP and ERP operations.\n4. Good working knowledge of Word, Excel, PowerPoint, or similar software.\n5. Ability to organize and coordinate internal and external resources, arranging them according to objectives, tasks, and formats to form a systematic and integrated whole.\n6. Continuously summarize, learn, and improve work methods to enhance personal and team efficiency and quality.\n7. Fluent in written and spoken Chinese and English.\n8. Steel industry experience preferred.\n9. Understanding of the company's quality, safety, environment, measurement, and IATF 16949 management systems.\n1、本科及以上学历\n2、订单管里全流程经验优先\n3、熟悉SAP、ERP操作\n4、良好的Word、Excel、PowerPoint或类似软件的操作知识\n5、组织协调内外部资源，按目的、任务和形式加以安排，使资源形成系统或整体\n6、自驱力强，愿意持续学习并优化工作方法，以提升个人及团队效率与工作质量\n7、流利的中英文书写和口语交流\n8、钢铁行业经验优先\n9、了解公司质量、安全、环境、测量及IATF16949管理体系",
