      "jd": "【岗位职责】\n1.BOM数据管理:负责编制、维护和优化BOM(物料清单)，确保其及时性、准确性和完整性。具体工作包括编制辅料 BOM、维护和优化ERP系统中的BOM信息、物料替代清单和损耗用量信息\n2.物料编码管理:按照公司物料编码规则，完成新物料申请、编码录入、物料信息完善，规范物料台账，定期清理重复物料、呆滞物料，优化物料库数据。\n3.工程变更落地:跟进设备设计变更、工艺优化、现场改制需求，及时更新BOM清单、变更记录，同步通知采购、生产、仓库、售后部门，确保变更闭环，杜绝新旧物料混用。\n4.生产用料支持:对接生产车间、采购部门，解答BOM物料疑问，处理生产领料异常、物料不符、缺料核查等问题，配合设备生产、装配、调试全流程物料保障。\n5.资料台账管理:负责BOM清单、物料明细、变更单据、图纸配套资料的分类存档、版本管控，建立标准化台账，保证资料可追溯、可查询。\n\n【任职要求】\n1.工作经验:1年以上设备制造行业BOM专员工作经验，熟悉非标成套设备、自动化设备BOM制作流程，有锂电设备设备行业经验者优先。\n2.技能要求\n-熟悉钣金机加件、标准件、电气常用物料规格;\n-熟练使用Office办公软件，会使用ERP系统录入、维护BOM数据;\n-熟悉设备物料编码规则、BOM层级结构逻辑。",
