      "jd": "生产跟单文员\n \n岗位职责\n \n1. 接收生产订单，整理工单、排产下单，跟进车间生产进度，跟进产品生产、返工、完工状态，确保按时交付，及时同步订单进度。\n2. 物料进出统筹安排：协助厂长负责车间生产物料申购、领料、退料、补料统筹跟进，管控物料出入库明细，核对物料数量、批次，杜绝物料缺料、积压、浪费问题，保障生产顺畅。\n3. 数据台账统计：熟练使用办公软件，每日登记生产进度、物料进出台账、订单完成数据，制作各类生产报表、物料报表，数据准确清晰。\n4. 内外对接协调：对接车间、仓库、品质岗位，生产遇缺料、延期、品质异常时及时沟通跟进、上报处理。\n5. 资料归档管理：负责订单单据、物料单据、生产文件的整理、分类、归档，保证账目、单据可追溯。\n6. 辅助品质对接：具备基础品质认知，可简单识别产品常见不良，协助记录品质异常、跟进返工整改，配合QC完成基础数据整理。\n \n任职要求\n \n1. 熟练电脑操作，精通Word、Excel表格制作与数据统计，能独立做各类台账报表。\n2. 有工厂生产跟单、物料文员、仓储统计经验优先，有机加工、五金厂品质经验者优先录用。\n3. 熟悉工厂物料进出、生产流程，具备基础统筹、协调能力。\n4. 工作细心严谨、责任心强，账目清晰，原则性强，沟通顺畅。\n5. 服从工作安排，稳定性高，能配合车间生产节奏，应届生肯学亦可。\n \n薪资福利\n \n1. 薪资：5000–7000元，经验丰富、懂品质物料统筹者薪资可面议\n2. 全勤奖、绩效奖、餐补，节假日福利。\n3. 办公环境舒适，团队氛围融洽，工作稳定，晋升空间良好。",
