      "jd": "一、岗位职责\n1、生产计划制定与跟进：根据订单需求及产能状况，协助制定并下发生产总计划，分解为月/周/日计划，并实时跟踪砂磨机等设备的生产进度，确保订单按期交付。\n2、物料需求管理（MRP）：统筹物料需求计划，结合BOM清单及库存数据，核算物料需求，跟进采购到货，有效预防生产缺料与呆滞库存。 \n3、跨部门协调：协调生产、采购、仓库、销售等部门，保障生产环节顺畅运行，及时处理物料、设备、人员等异常问题。\n4、数据统计与分析：统计生产数据（如产能利用率、工时效率、交期达成率），分析并反馈生产瓶颈，为持续优化流程提供数据支持。\n5、U9系统维护：负责U9系统（如用友等）中生产与物料相关数据的录入与维护，确保账实一致。\n二、任职要求\n1、学历专业：大专及以上学历，物流管理、供应链管理、工业工程、机械工程等相关专业优先。\n2、工作经验：1年以上制造业PMC、生产计划或物料控制相关经验；有砂磨机、研磨设备或机械装备行业经验者优先。优秀应届生亦可考虑。\n3、技能要求：熟练使用Office办公软件（Excel数据处理能力突出），熟悉ERP系统操作；了解生产制造基础流程，具备基本的产能分析与物料控制逻辑。\n4、综合素质：逻辑清晰，对数据敏感；沟通协调能力强，具备较强的责任心与抗压能力。",
