      "jd": "杭州燕源纳碳科技有限公司\n一、岗位职责\n1、负责单壁碳纳米管粉体、浆料生产所需原材料（如碳源、催化剂、溶剂、分散剂、包装材料等）以及生产设备、检测仪器、工程技改项目的寻源开发与采购执行；\n2、开展市场调研与供应商开发，收集行业价格、技术参数与产能信息，建立并维护合格供应商名录；\n3、组织询价、比价、议价及谈判，编制比价与采购分析报告，控制采购成本并落实降本目标；\n4、负责采购合同、订单的拟定与跟进，协同生产、研发、质量、工程部门完成物料、设备及工程项目的交期跟踪、到货验收与异常处理；\n组织供应商评审、绩效考核与关系维护，推动供应商在质量、交期与服务方面持续改善；\n5、建立采购台账与档案，跟踪价格行情、库存与物料齐套情况，完成采购数据分析与报表；\n6、协同工程、生产部门推进生产基地设备采购与工程建设项目的寻源开发及商务对接。\n二、任职资格\n1. 学历与专业：\n本科及以上学历，采购管理、供应链管理、材料、化工、机械、工程造价等相关专业；\n2. 经验要求：\n具有制造业采购或寻源经验，熟悉原材料、设备或工程类采购流程；\n有新材料、化工、新能源材料或装备制造行业采购经验者优先。\n3. 专业能力：\n熟悉采购流程、询比价与合同谈判，了解供应商开发与绩效管理方法；\n熟练使用 ERP 系统与 Office 办公软件，具备成本分析、价格谈判与合同风险识别能力。\n4. 素质要求：\n原则性强、廉洁自律，沟通协调与谈判能力突出，能够承受项目节点压力；工作严谨细致、责任心强，可适应阶段性出差（赴生产基地及供应商现场考察、验收）。\n5. 优先条件：\n具有碳材料或新能源材料原材料、非标设备或工程建设项目采购经验者优先。",
