      "jd": "岗位职责：\n1. 负责供应商日常对账工作，核对采购订单、送货单、入库单，做到三单匹配，确认送货数量、单价、金额无误。\n2. 收集、接收供应商进项发票，核对发票信息（抬头、税号、品名规格、数量、单价、税率、金额），检查发票与对账单、入库数据一致性，整理发票台账，登记发票明细 Excel 表。\n3. 跟进差异处理：对账过程中发现数量差异、价格异常、发票开错、单据缺失等问题，及时对接供应商、仓库、采购沟通核实、调整。\n4. 定期出具供应商对账单，发给供应商确认回传，归档对账资料、入库单据、发票复印件等原始资料。\n5. 将核对无误、资料齐全的对账单及发票，按时移交财务，配合财务完成发票认证、入账、付款排期工作。\n6. 完成上级安排的单据整理、数据统计、报表制作等相关工作。\n任职要求：\n1. 专科及以上学历，有制造业对账、采购文员、仓管单据核对相关经验优先，电气、线束行业经验加分。\n2. 熟练使用 Excel，擅长 VLOOKUP、数据透视表，能独立制作对账表、发票台账，数据敏感度高。\n3. 细心严谨，对数字敏感，原则性强，耐心沟通，能发现单据、发票数据错误。\n4. 了解增值税专用发票基础常识，熟悉采购入库对账流程优先。",
