      "jd": "职责描述：\n岗位概述\n1.负责按图纸定制加工类物料的供应商寻源、开发、比价、采购跟进及交付管控；熟悉机加工、钣金基础工艺与成本构成，保障定制件交期、质量与成本可控。\n主要工作职责\n1.供应商开发与寻源\n根据零部件 2D/3D 图纸、技术要求，开展机加工、钣金件供应商寻源、筛选、现场评估，建立合格供应商名录；拓展备选资源，降低单一供应商风险。\n2.询价、比价、核价与商务谈判\n看懂加工图纸，识别加工工艺、材料、表面处理、公差要求；能拆解加工成本构成（原材料、加工工时、机台、钣金折弯 / 焊接、表面处理、损耗、包装运费等），独立核价、比价，开展议价，控制采购成本，输出比价 / 核价记录。\n3.订单下达与交期管控\n完成采购需求评审，下达采购订单，跟进生产进度，跟踪生产、试做、样品、出货节点；识别延期风险，提前推动供应商整改，保障按时交付。\n4.样品与质量协同\n对接研发 / 工程，传递图纸、技术规范、检验标准；跟进首件样品打样、确认；来料出现尺寸、工艺不良时，联动品质、供应商分析原因，推动改善与索赔。\n5.文档与数据管理\n维护图纸版本、报价资料、供应商档案、采购合同、订单记录；更新价格、交期、良率数据，定期复盘供应商绩效。\n6.供应商绩效管理\n对供应商质量、交期、成本、服务进行定期评估，推动供应商持续改善，淘汰不合格供方。\n任职要求：\n1. 本科及以上学历，机械设计、机械制造、材料、模具等相关专业优先；\n2. 2 年及以上机加工、钣金定制件采购开发经验，熟悉设备结构件、非标零部件采购优先，有半导体设备零部件采购经验加分。\n3. 能够识读 2D 工程图纸，看懂公差、形位公差、表面处理要求，熟悉机加工（车 / 铣 / 磨 / CNC）、钣金（下料、折弯、焊接、喷涂、阳极氧化等）基础工艺；\n4. 具备独立成本拆解、核价、比价能力，可拆分原材料、工时、机台、表面处理、损耗、物流等成本项，独立开展商务议价；\n5. 熟悉非标定制件采购全流程：供方寻源、现场审核、样品打样、首件确认、订单跟进、交期风险管控、来料质量异常协同处理；\n6. 了解供应商绩效管理逻辑，可开展质量、交期、成本、服务维度评估，推动供方改善；\n7. 熟悉图纸版本、报价资料、供应商档案、订单台账等资料管理，能维护价格、良率、交期数据。",
