      "jd": "### 岗位职责\n\n1. 负责采购订单全流程跟进：订单录入、下发、交期确认、进度跟踪，同步供应商与内部需求部门，确保订单按期交付；\n2. 跟进物料到货、送货预约、到货通知，配合仓库做好收货核对，跟进到货异常、缺料、延期、分批到货等问题，及时预警；\n3. 订单台账维护：实时更新订单交期、到货状态、差异记录，定期输出订单跟踪报表，保证台账数据准确；\n4. 对接供应商：电话 / 邮件沟通交期、产能、发货安排，收集延期原因，推动供应商改善，同步内部生产 / 计划；\n5. 处理订单异常：物料品质异常、短装、错发、漏发、价格 / 规格差异等，协同质量、仓库、采购谈判跟进解决方案；\n6. 单据核对：核对送货单、采购订单、对账单信息一致性，协助采购做好对账、发票资料收集整理；\n7. 内部协同：对接生产计划、仓库、品质，及时同步物料风险，反馈缺料预警，支撑生产稳定；\n8. 完成上级安排的其他采购相关跟单、资料整理工作。\n\n### 任职要求\n\n1. 大专及以上学历，供应链、物流、采购相关专业优先；\n2. 1–3 年采购跟单、订单跟进、物控、供应链助理相关经验，**化工 / 精细化工 / 制造业经验优先**；\n3. 熟悉采购订单流程，看得懂物料规格、送货单，能独立跟进交期、处理异常；\n4. 熟练使用 Excel（VLOOKUP、数据透视表），会 ERP 系统操作（SAP / 用友 / 金蝶等）；\n5. 沟通能力良好，细心有耐心，抗压能力强，对交期敏感，有较强的风险意识；\n6. 具备基础英文读写能力（能看懂英文邮件、物料规格、供应商资料优先，适配外资化工企业）；\n7. 工作严谨，有台账管理习惯，善于记录、跟进闭环。",
