      "jd": "1. 负责公司行政类物资（办公用品、办公设备及耗材等）与食堂食材、餐厨物资的采购执行，涵盖需求归集、询价比价、订单下达、交付跟进与到货验收。\n2. 负责 ERP 系统内所有采购单据的录入、维护与流程闭环，确保采购数据准确、系统操作合规可追溯。\n3. 对接行政类与食堂类供应商，维护日常合作关系，跟进质量异议与售后问题，配合开展供应商评估与资源优化。\n4. 配合财务部门完成采购对账、票据整理及款项申请工作，同步建立食堂采购专项台账，做好成本统计与价格波动记录。\n5. 负责采购合同、单据、验收记录等资料的分类整理与归档管理，保证档案完整规范。\n6. 协助管控食堂食材品质与采购成本，配合落实食品安全相关采购要求，完成部门交办的其他采购辅助与行政协同工作。\n\n能力要求：\n1. 大专及以上学历，有行政采购相关工作经验者优先。\n2. 工作细心严谨、耐心踏实，具备较强的责任心与执行力，能妥善处理多品类细碎采购事务。\n3. 熟练操作 ERP 系统采购模块，精通 Office 办公软件，可独立使用 Excel 完成数据统计与台账维护。\n4. 具备基础的沟通协调能力，能顺畅对接内部各部门、食堂及外部供应商。\n5. 具备基础的食品安全与成本意识，了解常用食材、餐厨物资的验收标准者优先。\n6. 职业素养良好，严守工作纪律与采购合规要求，做事有条理。",
