      "jd": "【岗位定位】\n负责美线出口订单的全流程跟单与客户服务，客户以美线直客及同行客户为主，承接销售成交后的订舱出运、节点同步、异常处理与老客户维护，同时配合销售完成询报价支持与新客户落地。\n\n【岗位职责】\n1.负责美线海运出口订单的全流程跟单，涵盖订舱、放舱、拖车、报关、开船、对单放单、目的港清关及尾程派送等环节。\n2.对接国内客户与海外代理，同步船期、码头动态及各节点信息，处理甩柜、查验、延误、滞港费争议、目的港费用异议等常见异常。\n3.维护老客户，响应日常询报价与业务咨询，配合销售完成客户谈判及新客户落地。\n4.协调内部运营团队及海外代理、拖车行、报关行等供应商，推动订单顺畅执行。\n5.跟进业务过程中的突发情况，及时响应并协调解决客户及业务端的需求。\n6.配合完成费用核对与账单跟进，保障放单与结算环节顺畅。\n7.完成上级交办的其他相关工作。\n\n【任职要求】\n1.1—3年货代、国际物流、海运操作客服等相关工作经验，有美线客服、海外客服或操作经验者优先。\n2.英语可作为工作语言，能独立处理英文邮件，能进行日常口语沟通，对接海外代理及美国端团队。\n3.了解海运出口基本流程，熟悉订舱、拖车、报关、放舱、对单、放单等操作节点；有AMS/ISF申报、美国清关或尾程派送认知者优先。\n4.具备客户服务意识与异常处理能力，沟通协调顺畅，能承担一定抗压要求。\n5.接受国内白班为主、偶尔早班的工作节奏，接受根据业务安排的国内及国外出差。\n\n【岗位亮点】\n1.中美协同办公，英文邮件与口语作为日常工作语言之一，具备国际化业务视野。\n2.从订单承接、履约跟进到客户维护全流程参与，客服向运营/销售支持方向成长。\n3.配合销售谈判与客户攻坚，能力复合，晋升空间大。",
