      "jobKind": "2",
      "jd": "1.精准对接海外客户订单需求，将客户外销订单规范转化为工厂内部生产订单，核对产品型号、参数、数量、规格等核心信息，杜绝信息偏差，为工厂生产提供准确依据。\n2.全程落实订单各项细节，负责与客户及内部对接确认包装材质、包装标准、标识标签、出货交期、付款方式、特殊工艺要求等关键事宜，同步归档订单资料，确保信息清晰可追溯。\n3.作为订单核心对接人，联动销售、产品、研发、生产计划及自有工厂各环节，实时跟进生产进度，协调解决生产过程中出现的参数调整、物料、工艺、排产等各类问题，全程把控订单生产节奏，保障订单保质、保量、按时交付。\n4.负责对接海外客户指定验货机构、第三方验货公司及合作货代，统筹安排订单验货、报关、出货、物流跟进等全流程工作，整理核对出货单据，确保出货流程合规、顺畅，无误发、漏发、延迟出货等问题。\n5.协助部门完成海外客户来访接待、线上线下对接工作；负责样品寄送、样品测试进度跟进、测试结果反馈及记录归档；配合完成客户验厂对接、资料准备、现场协助等配套工作，维护良好的客户合作关系。\n6.协助销售团队对接海外客户基础询盘，解答客户关于产品规格、生产周期、出货标准、包装、交付流程等常规问题，同步记录客户需求，及时反馈跟进，辅助业务转化。\n7.服从部门工作安排，积极配合团队完成日常运营、订单台账整理、数据统计、资料归档等相关辅助工作。\n\n三、任职要求\n1. 大专及以上学历，英语CET-4及以上，国际贸易、商务英语等相关专业优先，具备熟练的英语日常读写能力，可独立看懂海外订单资料、客户邮件，完成基础英文沟通，能应对海外业务基础对接工作。\n2. 熟悉外贸出口全流程，具备1年及以上电子行业、新能源行业外贸跟单工作经验者优先；熟练掌握LC信用证操作流程、外贸单据制作与核对者优先。\n3. 熟练使用Word、Excel等办公软件，可独立完成订单台账、数据统计、报表整理、资料归档等工作，具备基础的单据处理能力。\n4. 具备优秀的内外沟通、统筹协调及问题解决能力，能够高效对接多部门及外部合作方，快速处理订单异常问题。\n5. 工作认真细致、踏实负责、反应敏捷，抗压能力良好，具备极强的责任心、执行力和团队协作精神，服从管理，主动推进工作落地。\n6. 有新能源、太阳能储能、移动电源、户外发电设备行业跟单经验者优先，熟悉工厂生产流程者加分。\n\n工作时间：早八晚五，周末双休。",
