      "jd": "Terms: Full time \nAbout the role: \nExport Merchandiser will be in charge of tracking and coordinating the entire order process—from order placement through to delivery—to ensure that goods are delivered according to the required specification, quantity, and schedule, while also assisting with procedures such as customs declaration, tax refund and foreign exchange settlement.\nResponsibilities: \n-\tOrder Follow-up：\n\tPlace purchase orders based on replenishment requirements from the operations team. \n\tCoordinate with factories to monitor production progress, lead times, and quality. \n\tAddress any production-related issues to ensure on-time delivery.\n-\tLogistics and Shipping: \n\tManage logistics from factories to Amazon fulfillment centers or overseas warehouses—including booking shipments, overseeing loading, preparing customs clearance documentation, tracking transit, and monitoring the status of arrivals and warehouse deliveries.\n-\tPlatform Shipment Operations: \n\tCreate shipment labels and shipping plans.\n\tCollaborate with the operations team to control shipping costs. \n\tResolve any issues that arise while shipments are in transit.\n-\tDocumentation and Accounting: \n\tPrepare and verify customs clearance documents, packing lists, and invoices. \n\tAssist the finance department with reconciliations, payments, and tax refund processing.\n-\tInventory and Data Management: \n\tRegularly compile data on placed orders, goods in transit, and warehouse stock.\n\tSupport the operations team in developing replenishment plans to prevent stockouts or overstocking, while improving inventory turnover.\n-\tAfter-Sales and Exception Handling: \n\tManage after-sales issues such as returns, refunds, and claims for lost shipments. \n\tFollow up on customer feedback and coordinate solutions.\nCandidate requirements:\n-\tAssociate degree or higher; majors in International Trade, Logistics/Supply Chain Management, or Business English are preferred.\n-\tAt least 2 years of experience in foreign trade order coordination/merchandising; experience with the Amazon e-commerce platform is a plus.\n-\tProficiency in English (CET-6 or higher), with strong skills in listening, speaking, reading, and writing.\n-\tProficient in the use of the MS Office suite.\n-\tStrong sense of responsibility, attention to detail, ability to work well under pressure, excellent communication and coordination skills, strong learning capacity, a proactive attitude, and a collaborative team spirit.",
