      "jobKind": "2",
      "jd": "岗位详情\n我们属于百人规模工贸‑一体工厂，岗位采用双线同步培养模式，入职即可一边深耕跟单基础、一边实操开发客户，不用等到培养周期结束才接触业务。\n1、跟单助理工作：订单下单、全程跟进生产、出货安排、对接货代、报关资料处理，保障每一笔订单顺利交付；\n2、外贸业务实操：公司分配平台询盘，负责英文邮件回复、报价、客户日常跟进，积累海外客户资源。\n完整培养周期 1 年左右，熟练之后转型独立外贸业务员，边上班边实战学习。\n岗位职责\n1.跟进外贸全流程，订单下达、生产跟进、出货核对、单证、货代以及报关对接；\n2.接收平台询盘，独立完成邮件回复、产品报价、客户日常维护；\n3.整理订单资料、客户档案，做好日常台账；\n4.服从主管工作安排，主动学习外贸业务知识，朝着外贸业务员方向成长。\n任职要求\n优先拥有 1 年左右外贸助理、跟单相关岗位经验，熟悉下单‑跟单‑出货‑报关整套外贸流程；无全职工作经验需为外贸相关专业、具备外贸实习经历，上手学习速度快；\n英语四级及以上，六级优先；英文读写能力扎实，可以看懂外贸单据、邮件，独立完成书面询盘回复，口语无硬性要求，愿意后期提升即可；\n做事细心严谨、条理清晰，能够应对繁琐的跟单工作，降低订单出错风险；\n执行力强、有耐心，具备基础客户服务意识；可以同时承担多项工作，主动好学；\n有长期发展规划，不愿意长期停留于助理岗位，立志往外贸业务员方向发展。\n优先加分项\n有询盘回复、报价、海外客户对接经验；\n熟悉阿里巴巴国际站等 B2B 外贸平台；\n熟悉报关流程、有货代对接经验。\n薪资福利\n试用期底薪：5500 元；转正底薪：6000 元  餐补费用是底薪额外的 试用期3个月 有月考核表\n额外订单毛利 6% 提成，多劳多得\n一对一新人带教、平台现成询盘资源、清晰的助理‑业务员晋升通道\n工厂办公环境简单，团队氛围轻松，人员流动性低",
