      "jd": "职位描述\n1．熟悉商务标和做技术标（要求会做，土建、安装、公路商务标)标书的制作，认真阅读招标文件要求，根据招标文件要求，收集制作招标文件需要的技术和商务资料。\n2．按招标文件要求，办理报名及保证金交纳等手续。\n3．按时完成投标文件的制作。\n4．认真审核投标文件中签字、盖章、名称等重要信息是否正确，是否符合招标文件的具体要求。\n5．按时完成投标文件、样品的密封。\n6．提供投标现场需要的资料。\n（二）标书信息整理\n1．对招标信息进行初步处理，根据商务信息要求、技术要求判断是否适合公司投标。\n2．将收集到的信息汇总后提交相关领导确定具体需要参与的项目，提交信息时应提供初步处理情况。\n3．信息结果查询：信息收集负责人应对当天开标的信息结果进行查询，确定信息中标单位及中标金额等重要信息。\n4．信息归档：每天对查询到的信息应归档到标书部共享移动硬盘内，供日后查询。\n（三）商务和技术资料的更新和归档\n1.投标文件制作完成后，对新收集的技术资料和商务资料应将原件保存在招投标组的移动硬盘\n内，供日后查询和使用。\n2.定期检查商务资料和技术资料的时效性，对超过有效期的资料和文件应及时删除，并向相关部门和供应商要求提供归档等工作。\n任职资格:\n1.有一年以上工作经验者优先；\n2.能适应加班等高强度工作者、有较强抗压能力者优先；\n3.熟练使用office、ps等办公软件；",
