      "jd": "岗位职责：\n1. 招标资料全流程归集编制：负责工程类招标项目招标文件、答疑补遗、控制价资料、投标单位资料、开标记录、评标资料、澄清说明、定标资料、中标 / 未中标通知书、合同前置资料等全套内页资料整理、校对、装订、归档；按公司及住建合规要求完成资料标准化组卷。\n2. 台账与数据管理：建立并动态维护招标项目台账，包含项目编号、招标范围、标段、报名单位、开标时间、评标结果、定标状态、资料闭环节点、档案存放位置；定期统计招标进度、资料逾期情况，输出招标数据简报。\n3. 线上流程与平台运维：负责招标采购系统 / 电子招投标平台信息录入、资料上传、流程发起、节点跟进；跟踪审批流，及时提醒经办人、评委完成线上签批，保证线上资料与纸质资料版本一致。\n4. 档案合规管理：执行工程档案管理制度，区分涉密 / 普通招标资料，做好借阅登记、归还核查、期限保管；配合内审、审计、住建稽查、上级检查，快速调取全套招标内页资料。\n5. 资质与供方资料管理：收集、归档投标单位资质、业绩、授权、人员证书等资料，核验资料有效期；维护合格供方档案库，同步更新供方基础资料。\n6. 标准化与协同支撑：梳理招标内页资料模板，持续优化标准化清单；配合招标经办、造价、法务完成资料复核；做好开标会务辅助、资料打印、密封、存档等支撑工作。\n7. 其他工作：完成主管交办的招标相关资料复核、历史项目档案补录、资料移交等临时工作。\n任职要求：\n1. 学历专业：本科及以上，工程管理、工程造价、土木工程、建筑、招投标相关专业优先。\n2. 经验要求：1–3 年建筑工程行业招标内页、资料管理、造价助理、招投标文员相关经验；熟悉土建、市政、安装工程招标流程，有国企 / 房企 / 建工单位档案管理经验优先。\n3. 专业能力：熟悉工程招标法规、招投标法、电子招投标流程；能看懂施工招标清单、招标范围，识别基础资料缺漏；熟练使用 Excel（台账、函数）、Word、PDF、飞书 / 钉钉流程、电子招投标平台。",
