      "jd": "岗位职责\n1.招标信息搜集：监控中国烟草电子采购平台、烟草工业公司采购公告，筛选公司相关产品采购项目，建立项目台账，记录标段、样品递交、截止时间、保证金节点。\n2.招标文件拆解：梳理资格条件、废标条款、技术参数、检测报告要求、样品要求、评分细则、CA 与电子签章规则，输出投标自查清单；重点核对检测报告有效期、体系证书、供货周期、质保要求。\n3.商务标书编制：编制全套商务投标文件；整理营业执照、生产资质、ISO9001/ISO14001 体系证书、财务审计报告、资信证明；信用中国、裁判文书网查询截图；烟草供应商禁入承诺书；同类货物供货业绩（合同 + 发票）；\n4.技术标资料整理：对接技术部门收集产品技术指标、第三方检测报告、安全技术说明书、质量保证方案、供货实施方案、售后服务方案；编制技术参数响应偏离表，逐条响应招标技术指标。\n5.烟草电子标全流程：维护平台账号、CA 数字证书；项目报名、购标、下载招标文件；使用投标客户端生成、预检、加密上传投标文件；处理澄清答疑；跟进保证金缴纳与退还；按项目要求完成样品寄送登记。\n6.标书校对排版：Word 高级排版、多级列表、自动目录、页眉页脚；PDF 处理；核对签字、电子签章；报价表复核；多轮自查防范废标。\n7.资质与档案管理：搭建公司相关产品投标资料库，证书、检测报告、业绩、定期更新，做证书到期预警；投标底稿、开标记录归档；严格保密产品数据、报价、供应商信息。\n8.纸质标书打印、密封、备份；跟踪开标结果，完成项目复盘。\n\n任职要求\n1.大专及以上学历，文秘、行政、化工相关专业优先；有货物类标书制作经验，做过香精香料、化工原料、烟用物资标书优先。\n2.熟练 Office：Word 高级排版、自动目录；Excel 表格运算；熟练 PDF 编辑处理。\n3.熟悉招投标流程，会操作中国烟草电子采购平台及投标客户端优先，掌握烟草货物标规则。\n4.能够读懂货物招标技术参数，独立编制技术偏离表；识别检测报告、体系证书时效风险。\n5.工作细致严谨，货物标参数、报告错漏直接造成废标；投标紧急节点可接受短期加班。\n6.较强保密意识，严格保密检测数据、报价、产品相关资料。",
      "source": "实名企业直招",
      "assessmentMethod": "2026-11-16保守规则复核＋重点样本人工复核，非HR资格确认",
