      "jd": "岗位职责：\n1. 信息搜集与跟踪： 负责搜集、筛选、跟踪与公司业务相关的招标信息，及时汇报招标公告。\n2. 标书编制与整合： 独立或协作完成商务标、技术标文件的编制、排版、打印、装订及密封等工作。\n3. 资料准备与管理： 负责投标所需各项资质的准备、整理与更新，如公司资质、人员证书、业绩证明等。\n4. 内容撰写与优化： 撰写、优化技术方案、服务方案、项目实施方案等文档内容，确保内容准确、有竞争力。\n5. 审核与校对： 严格对标书文件进行交叉审核与校对，确保无遗漏、无错别字、完全响应招标文件要求。\n6. 流程跟进与协调： 跟进投标全过程，包括报名、购买标书、保证金支付、投标、开标结果跟踪等。\n7. 资料归档： 负责投标结束后所有相关文件的整理、归档与保管。\n8. 完成上级交办的其他相关工作。\n\n---\n\n任职资格：\n\n必备要求：\n\n1. 学历专业： 大专及以上学历，文秘、行政管理、中文、市场营销或公司相关业务专业优先。\n2. 工作经验： 1年以上标书制作、文案编辑或相关文职类工作经验。有独立完成整套标书制作经验者优先。\n3. 技能要求：\n   · 精通Word、Excel、PPT等Office办公软件，尤其需要熟练掌握Word的排版、样式、页眉页脚等高级功能。\n   · 具备优秀的文字组织和书面表达能力，行文严谨、条理清晰。\n4. 素质要求：\n   · 极度细心与负责： 对细节有近乎苛刻的追求，能发现并修正细微错误。\n   · 抗压能力强： 能够适应投标前期的加班和高强度工作。\n   · 良好的沟通能力： 能与销售、技术、财务等多个部门高效协作，获取所需资料。\n   · 高度的时间观念： 能严格遵守并管理投标的各项截止日期。\n\n优先考虑：\n\n1. 熟悉政府采购流程及电子招投标平台（如各地公共资源交易中心）操作者。\n2. 了解《政府采购法》、《招标投标法》等基本法律法规。\n3. 会使用Photoshop、CAD等软件进行简单的图片或图纸处理者。\n\n\n\n· 薪酬福利： 薪资待遇（4-6k），绩效奖金、年终奖。\n· 上班时间：上午9:00-12:00   下午2:00-5:30周末双休。\n· 社会保障： 五险一金。\n· 假期福利： 带薪年假、国家法定节假日、节日福利等。\n·",
