      "jd": "一、岗位概述\n房建资料员主要负责建筑工程项目全过程资料收集、整理、编制、报审、归档工作，配合项目部完成施工资料、安全资料、试验资料、竣工资料的标准化管理，确保项目资料真实、完整、同步、合规，保障工程顺利验收、移交及结算。\n二、主要工作职责\n1. 施工资料管理\n根据施工进度同步编制、整理土建、装饰、安装等全套施工资料。\n负责工程开工资料、施工方案、技术交底、隐蔽记录、检验批、分部分项验收记录的填写、整理与报审。\n跟踪现场施工工序，确保资料与施工进度同步一致、真实对应，杜绝滞后、缺项、错项。\n配合监理、甲方进行资料检查、签字盖章、报验工作。\n2. 试验及材料资料管理\n负责进场材料、构配件、设备的合格证、检测报告、质保资料收集、整理、归档。\n跟进钢筋、水泥、砂石、砌块、防水材料等材料取样送检，登记试验台账。\n跟踪混凝土试块、砂浆试块、送检报告取回、整理、归档，及时预警过期、缺试、漏试问题。\n建立材料台账、试验台账、送检台账，做到有据可查。\n3. 安全、文明施工资料管理\n编制整理施工现场安全资料、三级安全教育、班前安全交底、安全检查记录、隐患整改资料。\n整理机械设备资料、特种作业人员证件、消防资料、文明施工、扬尘治理相关资料。\n配合住建局、监理、安全站各类检查资料准备及整改资料闭环。\n4. 变更、签证及过程资料\n收集工程变更、技术核定、现场签证、会议纪要、工作联系单等文件并分类归档。\n协助造价、施工员整理工程量、过程影像、佐证资料，为结算、审计提供依据。\n做好施工现场照片、影像资料留存，分阶段、分部位存档。\n5. 竣工资料整理与移交\n项目中后期开始系统整理全套竣工资料，按档案馆、建设单位标准组卷、装订、编号。\n负责竣工图纸整理、目录编制、资料汇总、移交清单整理。\n配合项目竣工验收、分户验收、档案馆备案及资料移交工作。\n6. 日常台账与文档管理\n建立完善的资料台账、文件收发台账、报审台账、借阅台账。\n项目部各类文件、通知、图纸、规范、方案统一归档管理。\n保证资料整洁、有序、分类清晰，随时可查、可检。\n三、任职要求\n中专/大专及以上，建筑工程相关专业，有无经验均可，接受应届生。\n熟悉房建项目施工资料流程、当地档案馆资料规范、资料组卷标准。\n熟练使用 Office 办公软件、CAD简单查看图纸，会资料软件者优先。\n细心严谨、责任心强、条理清晰，能跟上现场施工进度。\n服从项目部管理，能适应工地驻场、阶段性加班（竣工期）。\n具备良好沟通能力，能对接监理、甲方顺利完成资料签字报审。\n四、岗位优势\n工作稳定、技术性强，越做越吃香，可长期发展。\n主要为办公室文职工作，轻松不累，适合长期从事建筑文职岗位。\n可全程学习完整项目流程，快速提升专业能力。",
      "source": "实名企业直招",
