      "applicationStatus": "已投递",
      "reviewedAt": "2026-11-16",
      "jobKind": "2",
      "jd": "【我们是谁】\n一家专注于新能源充电桩（交流桩/直流桩）自主研发与生产的制造型企业，处于快速成长期。产品覆盖家用、公共运营、车队配套等场景，工厂具备完整装配与测试产线。现诚邀细心、有条理、愿意在供应链方向深耕的小伙伴加入运营团队。\n【岗位职责】\n1.生产计划协助：协助PMC主管制定周/日生产排程，跟踪生产进度，及时反馈异常（缺料、设备、人员等）。\n2.ERP系统维护：在ERP系统中录入/审核生产订单、领料单、入库单等，保证账实一致。\n3.库存监控：定期盘点在库物料（尤其是电子元器件、钣金件、线束等），预警呆滞料与安全库存。\n4.跨部门沟通：与采购、仓库、生产车间、质检部对接，传递计划指令，收集执行数据。\n5.报表输出：制作生产日报、物料齐套率分析表、计划达成率统计等基础报表。\n\n【任职要求】\n1.大专及以上学历，专业不限（物流、工业工程、工商管理、财会、计算机等专业优先）。\n2.应届生可投：无需正式工作经验，但需有较强的学习能力、逻辑清晰、对数据敏感。\n2.有经验者加分：1-2年生产文员、PMC助理、物控、仓管或跟单相关经验；熟悉工厂作业流程。\n技能要求\n1.熟练使用 Excel（数据透视表、VLOOKUP、SUMIFS等基础函数——面试时可能有简单测试）。\n2.接触过 ERP系统（如金蝶、用友、SAP、鼎捷或其他中小型ERP），了解基础出入库、工单模块操作。\n3.对数字敏感，能够快速核对物料清单与库存差异。\n4.细心、负责，能处理重复性录入工作而不出错。\n5.具备基本的抗压能力（充电桩旺季订单集中时需跟催物料）。\n6.沟通清晰，不怯于向车间或采购同事催单/确认进度。\n\n【我们提供】\n1.薪资：月薪5K-8K（13薪），具体根据学历、经验及面试表现定薪；应届生设3个月培养期，转正后有绩效奖金。\n2.培训：内部PMC流程带教 + ERP操作实训 + 充电桩产品知识培训（理解BOM结构与物料特性）。\n3.成长路径：PMC助理 → PMC专员 → 高级计划/物控主管 → 供应链经理\n4.福利：五险一金、工作餐补、提供住宿（或租房补贴）、节日福利、季度团建。\n5.工作氛围：扁平化管理，主管手把手带新人，产线透明，拒绝无效加班。",
