      "jd": "岗位职责：\n1、根据采购计划制定原料进口的年度、月度计划。\n2、根据计划进行海外原料的采购工作。\n3、做好海外供应商的开发及维护工作。\n4、做好采购合同执行，与供应商协调履行合同并及时发货等后续工作。\n5、联系货代，准备报关资料，开展到港后进口货物报关对账等相关工作。\n6、根据海关要求，对进口报关过程中货物存在的问题进行解答跟踪。\n7、将到货资料提交料仓，跟踪到货情况，并将到货中出现的问题反馈供应商，如有问题，跟踪处理并开展索赔工作。\n8、严格执行公司采购流程，严禁任何形式的收受回扣、利益输送或与供应商串通损害公司利益。\n岗位要求：\n1.一年以上海外再生有色采购（再生铜）相关工作经验，“本科学历且英语流利者，可适当放宽经验要求”；\n2.本科及以上学历，英语六级以上或可熟练进行日常交流——硬性条件；\n3.熟练使用办公系统软件；\n4.具备较强的沟通协调能力及责任心，能独立处理采购过程中的异常问题；\n5.无采购舞弊、受贿、围标串标等职业违规记录，接受合规背景调查。\n备注：\n具备海外采购/外贸跟单经验也可投递；\n熟悉有色金属行业者经验可不限制；\n若有有色金属行业海外采购者优先考虑。\n应届生也欢迎投递。",
