      "jd": "【公司简介】\n鲸宝集团总部位于宁波，在跨境物流持续深耕18年有余，在国内华东华南和美国洛杉矶等太平洋重要口岸均设有子公司(上海义乌苏州杭州吴江青岛临沂等)在欧美拥有数十个自营/合作和配送服务，公司已累计为超过4500家客户提供了数字化物流解决方案与服务，努力“让更多中国制造畅达全球”。\n\n【我们提供】\n周末双休（工作时间 9：00‑17：30，12：00-13：30午休）、五险一金、加班补贴、高温补贴、全勤奖、带薪年假、年度体检、节假日 / 生日惊喜福利、年终奖、激励奖金、季度团建、全员团建、各项培训等。完善的晋升通道，表现优异者可逐年逐级深度发展。\n年终奖！激励奖金！7h工作！\n\n【岗位职责】\n1. 负责海运进出口货物的全流程操作，包括订舱、放舱、SO 确认、拖车安排、报关、报检、提单制作与核对，确保货物按时出运。\n2. 跟进货物运输全过程，及时处理船公司、货代、报关行、仓库及海外代理之间的沟通协调，保障物流环节顺畅。\n3. 负责审核相关单证，如发票、装箱单、提单、报关资料等，确保单证信息准确、一致，符合美国海关及相关运输法规要求。\n4. 处理运输过程中的异常问题，包括但不限于甩柜、改单、查验、扣货、费用调整、舱位变动等，减少客户投诉和经济损失。\n5. 做好客户维护工作，主动同步物流信息，及时回复客户查询，解决客户在运输过程中的相关问题。\n6. 负责费用核算、账单核对及台账登记，确认各项费用的准确性，避免额外费用和错漏费用。\n7. 关注美国贸易政策、海关法规、航线规则及船公司通知变化，及时调整操作方式，防范单证不符、信息错误等操作风险。\n8. 与销售、操作、财务等部门紧密配合，确保业务流程高效运行，完成上级安排的其他工作任务。\n\n【任职要求】\n1. 大专及以上学历\n2. 货代1 年及以上海运物流操作或美线物流操作经验\n3. 熟悉海运出口操作流程，了解订舱、报关、报检、提单、舱单、AMS/ISF 等美线相关操作要求。\n4. 具备良好的英语基础，能够阅读英文提单、船公司通知及海外代理邮件。\n5. 熟练使用 Office 办公软件，尤其是 Excel，具备基础数据整理和费用核对能力。\n6. 性格开朗，沟通能力强，具备良好的跨部门协调能力和团队合作精神。\n7. 做事认真细致，责任心强，具备较强的抗压能力、学习能力和问题处理能力。\n8. 具备风险防范意识，能识别操作过程中的单证风险、费用风险和合规风险。",
