      "jobKind": "2",
      "jd": "负责纸品包装产品从开发样、产前样到大货样的跟进，包括订单资料整理、工艺单据制作、打样协调、样品核对及异常处理，确保资料准确、样品符合要求、交付及时。\n\n岗位职责\n1、整理业务及客户资料，核对产品规格、尺寸、材料、配件、数量、工艺及包装要求，制作样品单、工艺单、箱规单等资料，安排下单打样。\n2、全程跟进开发样、产前样及大货样，建立并更新进度台账，对接制版、工艺、车间及包材等部门，协调推进各节点，及时处理影响交期的问题。\n3、在系统中申购物料，跟进纸张、包材、配件及版辊到位情况，准确下发单据和确认资料，确保各部门使用的资料及版本一致。\n4、使用Photoshop、Adobe Illustrator进行基础图片和文件处理，包括查看、标注、简单修改及导出，对接制版公司完成文件确认与修改。\n5、对照客户要求、确认稿及工艺单，核对样品的尺寸、材料、结构、颜色和工艺效果；跟进大货首件，安排不合格样品整改、复样及再次核对。\n6、独立处理常见打样、制版及生产衔接问题，跟进客户修改要求，推动问题解决。涉及重大工艺变更或超出权限的事项，与相关技术负责人确认后推进。\n7、安排样品寄送并跟进反馈，整理确认样、彩稿、留样及订单记录，维护ERP/OA系统状态，完成资料归档及年度订单样册整理。\n\n任职要求\n1、大专及以上学历，专业不限，印刷包装相关专业优先。\n2、有1年以上印刷包装或相关纸制品工作经验；接受跟单、工艺、打样、包装品质、印前制作或包材开发等相关背景，具备实际样品跟进及生产对接经验。\n3、熟悉印刷及常见后道工艺，如覆膜、烫金、UV、模切、粘合成型等；能看懂产品规格、材料、配件及工艺要求，能够识别样品问题并推动整改。\n4、具备PS、Adobe Illustrator基础操作能力，能够完成简单图片及文件处理；熟练使用Excel、Word，能整理进度台账、制作单据并操作办公系统。\n5、能独立跟进样品及订单任务，沟通清楚、核对细致，能够同时管理多个任务的资料、版本和交期。\n6、能适应生产旺季工作节奏，配合必要的加班及现场跟进。",
      "source": "实名企业直招",
