      "jd": "一、岗位职责  \n1.采购计划与执行  \n根据库存预警及各部门需求（如环卫工具、清洁耗材、车辆配件等），制定采购计划，执行采购订单下达、跟单及催货。  \n处理紧急采购需求（如设备故障急需配件），保障一线作业不间断。  \n2.供应商全流程管理  \n开发、评估供应商（如清洁设备厂商、劳保用品商），建立合格供应商库并持续优化。  \n负责比价议价（至少3家比价），控制成本，签订合同并跟进履约（如车辆维修配件交付时效）。  \n3.物资验收与质量控制\n核对到货物资规格、数量及质量（如扫帚耐用性、洗扫车配件兼容性），处理退货、索赔等异常。  \n协同技术部门对环卫设备（如洒水车、抑尘车）进行验收调试。  \n4.成本与单据管理  \n定期调查物料市场价格（如柴油、垃圾袋、融雪剂），提交成本分析报告。  \n管理采购合同、发票及出入库单据，确保财务核销合规。  \n5.后勤协同支持  \n配合资产盘点（如环卫车辆、维修工具），协助报废流程。  \n参与招标文件准备（如大型设备采购），对接售后问题。 \n\n二、任职要求\n1.大专及以上（优秀应届生可放宽，需相关专业如物流/供应链管理）环卫行业经验者优先。\n2.1-3年采购经验（应届生需实习/项目经历），熟悉办公用品、五金配件等品类。\n3.熟练使用Excel（数据汇总）、Word（合同）、ERP系统，会操作采购管理软件加分。\n4.具备成本意识，优化采购成本；合规操守，严守财务纪律及沟通协调能力。",
