      "jd": "一、工作内容\n\n1.单证制作与审核：负责国际海运（美/加线）业务全流程航运单证操作。核心是在船舶截港前，精准、及时地完成补料、VGM提交及海关申报（AMS/ISF/ACI）\n2.流程节点把控：同步订舱、报关、截单进度；跟踪单证流转状态，记录关键节点（如截单时间、放行时间）。\n3.异常处理与归档：海关查验延误及目的港清关问题，保障货物顺利装船出运。同时处理改单、转船、放货查询及危险品单证\n4.跨岗协同：配合操作部订舱、报关、派送岗位，同步单证信息；对接客户、代理补充单证资料，确保沟通高效、信息同步。\n\n二、任职要求：\n1、1年以上货运代理单证、报关或船公司单证操作经验。\n2、熟悉集装箱海运单证流程，了解美国AMS/ISF、加拿大ACI申报要求。\n2、具备良好的沟通协调能力和团队合作精神。\n3、有责任心、工作细致认真，具备工作计划能力、规范操作能力和执行力。\n4、熟练使用办公软件及单证系统，能高效完成数据录入与核对。\n5、有COSCO、ZIM等船公司系统实操经验者优先。\n\n三、薪资待遇\n薪资6-10k，底薪+绩效\n1、5.5天工作制  （周一至周五9:00-12:00  14:00-18:00；周六9:00-12:00）\n2、法定节假日、五险一金、年终奖\n3、传统节日红包，过年提前一周放假\n4、业务增长快，晋升空间广阔\n\n四、上班地点\n深圳市龙岗区坂田街道办坂澜大道荣德昌科技大厦B座12层",
