      "jd": "Responsible for preparing, verifying, and filing the complete set of import and export documentation, including but not limited to invoices, packing lists, bills of landing, certificates of origin, and licenses, ensuring consistency among documents and between documents and shipments. Familiar with relevant customs laws and regulations, and coordinate customs clearance procedures across departments in accordance with customs requirements.\n负责进出口全套单证的制作、核对与归档，包括但不限于发票、装箱单、提单、原产地证、许可证等，确保单证相符、单单一致。熟悉海关相关法律法规，以海关规范要求对各部门的报关业务进行协调。\nCoordinate with customs brokers, customs authorities, and government agencies such as commodity inspection to provide accurate declaration documents, handle inspection and tax payment procedures, track the progress of customs clearance and tax remittance, resolve any anomalies arising during the clearance process, and ensure smooth customs clearance.\n配合报关行及海关、商检等政府部门，提供准确的申报资料，处理查验、缴税等事宜，跟进报关、缴税及放行进度，处理清关过程中的异常问题，确保通关顺畅。\nDevelop inventory plans, optimize inventory structure, establish inventory turnover ratios, and set targets for stockout rates.\n制定库存计划，优化库存结构，制定库存周转率，缺货率控制目标。\nFollow up on the procurement plan and, once the purchase order is issued, manage end-to-end tracking.\n跟进采购计划，采购订单下达后，负责全流程跟踪。\nResponsible for supporting logistics services regarding materials related to other departments (e.g., Technical Service, Field Service).\n负责协助公司其它部门相关物料物流服务。（如技术服务， 现场服务等）\nDaily SAP system operations, including but not limited to entering product batch numbers, expiration dates, and other relevant information.\n日常SAP系统操作，包括但不限于产品的批次，有效期等相关信息的录入。\n要求：\nEducation:  Bachelor’s degree or above; candidates with a background in International Trade, Logistics Management, Supply Chain Management, or English-related fields are preferred.\n本科以上学历，国际贸易，物流管理，供应链管理或英语相关专业优先。\nExperience: 2+ years of experience in import and export logistics operations; familiar with air freight, ocean freight, and international express shipping procedures.\n2年以上进出口物流操作相关经验；熟悉空运、海运及国际快递操作流程。 \nCertification/Licensure:  Able to meet the English language proficiency requirements for typical work conditions in listening, speaking, reading, and writing.\n可满足一般工作条件下的英语听说读写能力。\nOther: Familiar with ERP systems and Microsoft Office, with strong data collection and analysis skills.\n\n覆盖医药类产品进出口全套单证制作、海关清关全流程协调，满足其大量实验室设备、试剂的跨境流转需求；\n涉及产品批次、有效期的SAP系统录入，完全匹配医药行业GSP合规要求下的效期、批号全链路追溯规则；\n库存计划制定、库存周转率与缺货率管控，适配其高值医药试剂、精密实验设备的库存精细化管理需求。",
